# Generated by build.py from recipe.yml for recipe gopher-walk-menus-into-subfolders. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site/notes', 'site/notes/archive', 'bare' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/notes/today.txt'), "nothing happened`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/notes/archive/2025.txt'), "old news`n")
[IO.File]::WriteAllText((Join-Path $PWD 'bare/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'walk.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh walk.sh PORT. Starts at the root menu, follows the first directory entry`n# of each menu until a menu has none, then fetches the first file that menu lists.`nbase=gopher://127.0.0.1:`$1`nsel=`"`"`nwhile :; do`n  menu=`$(curl -s `"`$base/1`$sel`" | tr -d '\r')`n  next=`$(printf '%s\n' `"`$menu`" | awk -F'\t' '/^1/ { print `$2; exit }')`n  [ -z `"`$next`" ] && break`n  echo `"menu `${sel:-/} -> `$next`"`n  sel=`$next`ndone`nfile=`$(printf '%s\n' `"`$menu`" | awk -F'\t' '/^0/ { print `$2; exit }')`necho `"file `$file`"`ncurl -s `"`$base/0`$file`"`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--list-directories', 'gopher://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh walk.sh 8080 } finally { Stop-Process $server0 }
